import React, { useState } from "react";
import { Link } from "react-router-dom";
import "./ProductList.scss";

const Product = ({ product }) => {
  const [imageLoaded, setImageLoaded] = useState(false);

  if (!product) {
    return <div className="product">Produto não encontrado.</div>;
  }

  // Verifica se a estrutura do produto está correta
  const items = product.items?.[0];
  const sellers = items?.sellers?.[0];
  const commertialOffer = sellers?.commertialOffer;

  // Preço à vista
  const price = commertialOffer?.Price;
  const priceVista =
    price && price > 0 ? `R$ ${price.toFixed(2)}` : "Preço não disponível";

  // Parcelamento
  const installments = commertialOffer?.Installments?.[0];
  const priceParcelado =
    installments && installments.Value > 0
      ? `${installments.NumberOfInstallments}x de R$ ${installments.Value.toFixed(2)}`
      : "Parcelamento não disponível";

  const handleBuy = () => {
    alert(`Você comprou: ${product.productName}`);
  };

  return (
    <div className="product">
      <img
        src={product.items?.[0]?.images?.[0]?.imageUrl || "/no-image.jpg"} // Fallback para imagem não encontrada
        alt={product.productName}
        onLoad={() => setImageLoaded(true)}
        onError={(e) => {
          e.target.src = "/no-image.jpg"; // Fallback para imagem não encontrada
        }}
      />
      <Link to={`/produto/${product.productId}`} className="product-link">
        <h3 className="product-name">{product.productName}</h3>
      </Link>
      <p className="price-vista">{priceVista}</p>
      <p>{priceParcelado}</p>
      <button className="buy-button" onClick={handleBuy}>QUICK SHOP</button>
      <br />
      <br />
    </div>
  );
};

export default Product;
